mapper.select:
/* com.kyj.fmk.common.mapper.CommonMapper.cmCdlist 공통코드 조회 */ SELECT CMC.CM_CD , CMCD.CM_CD_VAL , CMCD.CM_CD_VAL_NM FROM CM_CM_CD CMC INNER JOIN CM_CM_CD_D CMCD ON CMC.CM_CD = CMCD.CM_CD WHERE 1=1
AND CMC.CM_CD = #{cmCd}
AND CMCD.CM_CD_VAL = #{cmCdVal}
AND CMC.US_YN = 'Y'

/* com.kyj.fmk.common.mapper.CommonMapper.skillCdlist 기술스택 조회 */
SELECT CSC.SKILL_CD
     , CSC.SKILL_NM
     , CSC.SKILL_CD_IMG
  FROM CM_SKILL_CD CSC
 WHERE 1=1

       AND CSC.SKILL_CD = #{skillCd}


       AND CSC.DTY_CD = #{dtyCd}

       AND CSC.US_YN  = 'Y'

/* com.kyj.fmk.common.mapper.CommonMapper.dtyCdList 직무코드 조회 */ SELECT CDC.DTY_CD , CDC.DTY_NM , CDC.DTY_CD_IMG FROM CM_DTY_CD CDC WHERE 1=1
AND CDC.DTY_CD = #{dtyCd}
AND CDC.US_YN = 'Y'
